async function woo(path,init={}){const u=new URL(`${storeUrl}/wp-json/wc/v3${path}`);u.searchParams.set("consumer_key",process.env.WOOCOMMERCE_CONSUMER_KEY);u.searchParams.set("consumer_secret",process.env.WOOCOMMERCE_CONSUMER_SECRET);const r=await fetch(u,{...init,headers:{"Content-Type":"application/json",...(init.headers||{})},signal:AbortSignal.timeout(90000),cache:"no-store"});const b=await r.json().catch(()=>null);if(!r.ok)throw new Error(`${path} ${r.status}: ${JSON.stringify(b)?.slice(0,400)}`);return b;}
async function categoryId(name){const a=await woo(`/products/categories?search=${encodeURIComponent(name)}&per_page=20`);return a.find(x=>x.name.toLowerCase()===name.toLowerCase())?.id||(await woo("/products/categories",{method:"POST",body:JSON.stringify({name})})).id;}
